// ========================================================
// XỬ LÝ DỮ LIỆU TỪ AI & TẠO ẢNH BÌA TỰ ĐỘNG (POLLINATIONS FLUX)
// ========================================================
const rawResponse = $input.item.json.text || $input.item.json.response || '';
let data = {};

try {
  // Làm sạch các thẻ bọc nếu AI lỡ xuất ra ```json
  const cleanJson = rawResponse.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(cleanJson);
} catch (e) {
  data = {
    type: 'Prompt AI',
    title: 'Prompt Chân Dung Nghệ Thuật Ánh Sáng Tự Nhiên Đỉnh Cao',
    labels: ['Image Prompt', 'Công cụ hình ảnh Ai'],
    prompt_english: 'Cinematic portrait of a Vietnamese female model in traditional modern silk dress at golden hour 8k --ar 16:9',
    model_name: 'Flux 1.1 Pro',
    aspect_ratio: '16:9',
    style_name: 'Photorealistic',
    keywords_breakdown: [
      {keyword: 'golden hour', explanation: 'Tạo ánh sáng vàng hoàng hôn ấm áp.'},
      {keyword: '85mm lens', explanation: 'Tạo độ sâu trường ảnh và xóa phông mịn màng.'}
    ],
    tip_box: 'Hãy thử đổi tỷ lệ thành 9:16 nếu bạn muốn đăng ảnh lên story TikTok hoặc Facebook.',
    summary: 'Khám phá câu lệnh prompt độc đáo giúp bạn tạo ra những bức ảnh nghệ thuật đầy cảm xúc.'
  };
}

// Tạo link ảnh AI chuẩn độ phân giải cao miễn phí qua Pollinations FLUX API
const imgPromptEncoded = encodeURIComponent(data.image_prompt || data.prompt_english || 'futuristic ai automation technology');
const autoImageUrl = `https://image.pollinations.ai/prompt/${imgPromptEncoded}?width=1280&height=720&nologo=true&seed=${Math.floor(Math.random() * 100000)}`;

// Ráp vào khung HTML Template chuẩn của Nguyen Dang AI
let htmlBody = '';

if (data.type === 'Prompt AI') {
  // --- TEMPLATE 4: IMAGE PROMPT AI ---
  let keywordsHtml = '';
  if (data.keywords_breakdown && Array.isArray(data.keywords_breakdown)) {
    keywordsHtml = data.keywords_breakdown.map(k => `<li><strong>${k.keyword}:</strong> ${k.explanation}</li>`).join('');
  }

  htmlBody = `
<div class="separator" style="clear: both; text-align: center; margin: 20px 0 26px;">
  <img border="0" src="${autoImageUrl}" alt="${data.title}" style="max-width: 100%; border-radius: 14px; box-shadow: 0 8px 25px rgba(0,0,0,0.1);" />
  <div style="font-size: 13px; color: #64748b; margin-top: 8px; font-style: italic;">
    Hình ảnh được sinh tự động theo Prompt bên dưới (Model: ${data.model_name || 'Flux 1.1 Pro'})
  </div>
</div>

<div style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 18px 22px; margin-bottom: 24px; box-shadow: 0 4px 6px -1px rgba(0,0,0,0.03); font-family: 'Be Vietnam Pro', sans-serif;">
  <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(130px, 1fr)); gap: 14px; font-size: 13.5px;">
    <div><span style="color: #64748b; font-size: 12px; display: block;">Mô hình AI:</span><strong style="color: #4f46e5;">${data.model_name || 'Flux 1.1 Pro'}</strong></div>
    <div><span style="color: #64748b; font-size: 12px; display: block;">Tỷ lệ khung hình:</span><strong style="color: #0f172a;">${data.aspect_ratio || '16:9'}</strong></div>
    <div><span style="color: #64748b; font-size: 12px; display: block;">Phong cách:</span><strong style="color: #ec4899;">${data.style_name || 'Cinematic'}</strong></div>
    <div><span style="color: #64748b; font-size: 12px; display: block;">Độ phân giải:</span><strong style="color: #10b981;">4K Ultra HD</strong></div>
  </div>
</div>

<h3>🎨 Câu Lệnh Prompt Chính Thức (Positive Prompt)</h3>
<div style="position: relative; margin-bottom: 24px;">
  <button onclick="navigator.clipboard.writeText(document.getElementById('aiPromptText').innerText); alert('Đã sao chép prompt!');" style="position: absolute; right: 14px; top: 14px; background: linear-gradient(135deg, #ec4899 0%, #8b5cf6 100%); color: #ffffff; border: none; padding: 7px 16px; border-radius: 8px; font-size: 12.5px; font-weight: 700; cursor: pointer; box-shadow: 0 4px 10px rgba(236, 72, 153, 0.3);">
    📋 Sao Chép Prompt
  </button>
  <div id="aiPromptText" style="background: #0f172a; color: #f8fafc; border-radius: 14px; padding: 24px; font-family: monospace; font-size: 14px; line-height: 1.7; border: 1px solid #1e293b; padding-right: 140px;">
    ${data.prompt_english}
  </div>
</div>

<h3>Phân tích từ khóa cốt lõi trong Prompt</h3>
<ul>
  ${keywordsHtml}
</ul>

<div style="background: #fdf4ff; border: 1px solid #f0abfc; border-left: 4px solid #c026d3; padding: 16px 20px; border-radius: 0 12px 12px 0; margin: 24px 0; font-size: 14px; color: #701a75;">
  <strong>💡 Gợi ý tùy biến:</strong> ${data.tip_box || 'Bạn có thể thay đổi bối cảnh hoặc ánh sáng để tạo ra phong cách riêng.'}
</div>`;

} else {
  // --- TEMPLATE 3: HƯỚNG DẪN THỦ THUẬT ---
  let stepsHtml = '';
  if (data.tutorial_steps && Array.isArray(data.tutorial_steps)) {
    stepsHtml = data.tutorial_steps.map(s => `
<div style="display: flex; gap: 18px; margin-bottom: 24px;">
  <div style="flex-shrink: 0; width: 38px; height: 38px; border-radius: 50%; background: #4f46e5; color: #ffffff; display: flex; align-items: center; justify-content: center; font-weight: 800; font-size: 15px;">
    ${s.step}
  </div>
  <div>
    <h4 style="margin-top: 2px; margin-bottom: 8px; font-size: 17px; color: #0f172a;">${s.title}</h4>
    <p style="color: #475569; font-size: 14.5px; line-height: 1.7;">${s.content}</p>
  </div>
</div>`).join('');
  }

  htmlBody = `
<div style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 14px; padding: 20px; margin: 20px 0 28px; font-family: 'Be Vietnam Pro', sans-serif;">
  <span style="background: #ecfdf5; color: #059669; font-weight: 700; font-size: 12px; padding: 3px 10px; border-radius: 20px;">📚 BÀI HƯỚNG DẪN</span>
  <p style="font-size: 15px; color: #334155; line-height: 1.6; margin-top: 10px;">${data.summary}</p>
</div>

<div class="separator" style="clear: both; text-align: center; margin: 20px 0;">
  <img border="0" src="${autoImageUrl}" alt="${data.title}" style="max-width: 100%; border-radius: 12px;" />
</div>

<h3>Các bước thực hiện chi tiết:</h3>
<div style="margin: 24px 0;">
  ${stepsHtml}
</div>

<div style="background: #f0fdf4; border: 1px solid #bbf7d0; border-left: 4px solid #16a34a; padding: 16px 20px; border-radius: 0 12px 12px 0; margin: 24px 0; font-size: 14.5px; color: #166534;">
  <strong>💡 Mẹo thực chiến:</strong> ${data.tip_box || 'Kiểm tra kỹ kết nối trước khi bật chạy chính thức.'}
</div>`;
}

return {
  json: {
    title: data.title,
    content: htmlBody,
    labels: data.labels || ['Tin tức Ai', 'Hướng dẫn'],
    summary: data.summary,
    imageUrl: autoImageUrl,
    blogId: '2562876275428955705'
  }
};

